/* 重新配置前先复位 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1, ENABLE);
ADC_DeInit(ADC1);

/* 复位后必须重新初始化 + 重新校准 */
ADC_Init(ADC1, &ADC_InitStructure);
ADC_Cmd(ADC1, ENABLE);

GPIO_InitTypeDef GPIO_InitStructure;
ADC_InitTypeDef ADC_InitStructure;

/* 1. 开时钟：ADC1 时钟必须开 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1 | RCC_APB2Periph_GPIOA, ENABLE);

/* 2. ADC 时钟 = PCLK2/6 = 12MHz，不得超过 14MHz */
RCC_ADCCLKConfig(RCC_PCLK2_Div6);

/* 3. PA0 配成模拟输入 */
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_0;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AIN;
GPIO_Init(GPIOA, &GPIO_InitStructure);

/* 4. 配置 ADC：单通道、单次、软件触发、右对齐 */
ADC_InitStructure.ADC_Mode = ADC_Mode_Independent;
ADC_InitStructure.ADC_ScanConvMode = DISABLE;
ADC_InitStructure.ADC_ContinuousConvMode = DISABLE;
ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_None;
ADC_InitStructure.ADC_DataAlign = ADC_DataAlign_Right;
ADC_InitStructure.ADC_NbrOfChannel = 1;
ADC_Init(ADC1, &ADC_InitStructure);

/* 5. 使能 + 校准（顺序不能变） */
ADC_Cmd(ADC1, ENABLE);
ADC_ResetCalibration(ADC1);
while (ADC_GetResetCalibrationStatus(ADC1));
ADC_StartCalibration(ADC1);
while (ADC_GetCalibrationStatus(ADC1));

ADC_InitTypeDef ADC_InitStructure;

ADC_StructInit(&ADC_InitStructure);
/* 默认外部触发是 T1_CC1，软件触发必须改成 None，否则不转换 */
ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_None;
ADC_Init(ADC1, &ADC_InitStructure);

/* 使能与校准的固定顺序，一步都不能少 */
ADC_Cmd(ADC1, ENABLE);                    /* 1. 使能 ADC */

ADC_ResetCalibration(ADC1);               /* 2. 复位校准寄存器 */
while (ADC_GetResetCalibrationStatus(ADC1));

ADC_StartCalibration(ADC1);               /* 3. 开始校准 */
while (ADC_GetCalibrationStatus(ADC1));

/* 4. 之后才能开始转换 */
ADC_SoftwareStartConvCmd(ADC1, ENABLE);

/* ADC1 多通道扫描 + DMA 搬运到数组 */
DMA_InitTypeDef DMA_InitStructure;

RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA1, ENABLE);

DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&ADC1->DR;  /* ADC 结果寄存器 */
DMA_InitStructure.DMA_MemoryBaseAddr = (uint32_t)adcBuf;
DMA_InitStructure.DMA_DIR = DMA_DIR_PeripheralSRC;
DMA_InitStructure.DMA_BufferSize = 4;
DMA_InitStructure.DMA_PeripheralInc = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;
DMA_InitStructure.DMA_MemoryDataSize = DMA_MemoryDataSize_HalfWord;
DMA_InitStructure.DMA_Mode = DMA_Mode_Circular;   /* 循环模式持续刷新 */
DMA_InitStructure.DMA_Priority = DMA_Priority_High;
DMA_InitStructure.DMA_M2M = DMA_M2M_Disable;
DMA_Init(DMA1_Channel1, &DMA_InitStructure);
DMA_Cmd(DMA1_Channel1, ENABLE);

ADC_DMACmd(ADC1, ENABLE);

NVIC_InitTypeDef NVIC_InitStructure;

NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);
NVIC_InitStructure.NVIC_IRQChannel = ADC1_2_IRQn;   /* ADC1/ADC2 共用 */
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

ADC_ITConfig(ADC1, ADC_IT_EOC, ENABLE);
ADC_SoftwareStartConvCmd(ADC1, ENABLE);

void ADC1_2_IRQHandler(void)
{
  if (ADC_GetITStatus(ADC1, ADC_IT_EOC) != RESET)
  {
    adcValue = ADC_GetConversionValue(ADC1);   /* 读 DR 自动清 EOC */
  }
}

/* 使用 ADC 前必须完整走一遍校准 */
ADC_Cmd(ADC1, ENABLE);

ADC_ResetCalibration(ADC1);
while (ADC_GetResetCalibrationStatus(ADC1));   /* 等复位校准完成 */

ADC_StartCalibration(ADC1);
while (ADC_GetCalibrationStatus(ADC1));        /* 等校准完成 */

/* 现在才能开始转换 */

ADC_ResetCalibration(ADC1);
while (ADC_GetResetCalibrationStatus(ADC1));   /* 等到返回 RESET 才继续 */
ADC_StartCalibration(ADC1);
while (ADC_GetCalibrationStatus(ADC1));

/* 完整校准流程（ADC 初始化后必做） */
ADC_Cmd(ADC1, ENABLE);

ADC_ResetCalibration(ADC1);
while (ADC_GetResetCalibrationStatus(ADC1));

ADC_StartCalibration(ADC1);
while (ADC_GetCalibrationStatus(ADC1));

/* 校准完成后才能开始转换 */
ADC_SoftwareStartConvCmd(ADC1, ENABLE);

ADC_StartCalibration(ADC1);
while (ADC_GetCalibrationStatus(ADC1));   /* 校准完成前不能转换 */
ADC_SoftwareStartConvCmd(ADC1, ENABLE);

/* 单次采样 PA0，轮询方式 */
uint16_t GetAdcValue(void)
{
  ADC_SoftwareStartConvCmd(ADC1, ENABLE);
  while (ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC) == RESET);  /* 等转换完成 */
  return ADC_GetConversionValue(ADC1);                     /* 读 DR 会清 EOC */
}

/* 4 通道规则组，每次触发转 1 个 */
ADC_DiscModeChannelCountConfig(ADC1, 1);
ADC_DiscModeCmd(ADC1, ENABLE);

/* 4 通道规则组，中断模式下每次只转 1 个通道 */
ADC_DiscModeChannelCountConfig(ADC1, 1);
ADC_DiscModeCmd(ADC1, ENABLE);

/* 4 通道规则组扫描：PA0/PA1/PA2/PA3 */
ADC_InitStructure.ADC_ScanConvMode = ENABLE;
ADC_InitStructure.ADC_NbrOfChannel = 4;
ADC_Init(ADC1, &ADC_InitStructure);

/* Rank 从 1 开始；采样时间按信号源内阻选 */
ADC_RegularChannelConfig(ADC1, ADC_Channel_0, 1, ADC_SampleTime_55Cycles5);
ADC_RegularChannelConfig(ADC1, ADC_Channel_1, 2, ADC_SampleTime_55Cycles5);
ADC_RegularChannelConfig(ADC1, ADC_Channel_2, 3, ADC_SampleTime_55Cycles5);
ADC_RegularChannelConfig(ADC1, ADC_Channel_3, 4, ADC_SampleTime_55Cycles5);

/* 多通道必须配 DMA，否则 DR 会被覆盖 */
ADC_DMACmd(ADC1, ENABLE);

/* TIM2 更新事件周期触发 ADC1 采样 */
ADC_InitStructure.ADC_ExternalTrigConv = ADC_ExternalTrigConv_T2_CC2;
ADC_Init(ADC1, &ADC_InitStructure);

ADC_ExternalTrigConvCmd(ADC1, ENABLE);   /* 打开外部触发 */

/* 单通道轮询采样 */
uint16_t ReadAdc(uint8_t channel)
{
  ADC_RegularChannelConfig(ADC1, channel, 1, ADC_SampleTime_55Cycles5);
  ADC_SoftwareStartConvCmd(ADC1, ENABLE);
  while (ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC) == RESET);
  return ADC_GetConversionValue(ADC1);   /* 读 DR 自动清 EOC */
}

/* 双重模式同时读 ADC1(PA0) 与 ADC2(PA1) */
uint32_t both = ADC_GetDualModeConversionValue();
uint16_t adc1Val = (uint16_t)(both & 0xFFFF);        /* 低 16 位 = ADC1 */
uint16_t adc2Val = (uint16_t)(both >> 16);           /* 高 16 位 = ADC2 */

/* 注入组单通道软件触发采样 */
ADC_InjectedSequencerLengthConfig(ADC1, 1);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_1, 1, ADC_SampleTime_55Cycles5);

ADC_SoftwareStartInjectedConvCmd(ADC1, ENABLE);
while (ADC_GetFlagStatus(ADC1, ADC_FLAG_JEOC) == RESET);
value = ADC_GetInjectedConversionValue(ADC1, ADC_Channel_1);

/* 注入组 2 通道 */
ADC_InjectedSequencerLengthConfig(ADC1, 2);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_4, 1, ADC_SampleTime_41Cycles5);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_5, 2, ADC_SampleTime_41Cycles5);

/* 3 个注入通道 */
ADC_InjectedSequencerLengthConfig(ADC1, 3);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_4, 1, ADC_SampleTime_41Cycles5);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_5, 2, ADC_SampleTime_41Cycles5);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_6, 3, ADC_SampleTime_41Cycles5);

/* 注入组 2 个通道 */
ADC_InjectedSequencerLengthConfig(ADC1, 2);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_1, 1, ADC_SampleTime_55Cycles5);
ADC_InjectedChannelConfig(ADC1, ADC_Channel_2, 2, ADC_SampleTime_55Cycles5);

ADC_SoftwareStartInjectedConvCmd(ADC1, ENABLE);
while (ADC_GetFlagStatus(ADC1, ADC_FLAG_JEOC) == RESET);

/* 参数是注入序列位置，不是引脚通道号 */
v1 = ADC_GetInjectedConversionValue(ADC1, ADC_InjectedChannel_1);
v2 = ADC_GetInjectedConversionValue(ADC1, ADC_InjectedChannel_2);

/* 监视 PA0，超出 500~3500 就报警 */
ADC_AnalogWatchdogThresholdsConfig(ADC1, 3500, 500);
ADC_AnalogWatchdogSingleChannelConfig(ADC1, ADC_Channel_0);
ADC_AnalogWatchdogCmd(ADC1, ADC_AnalogWatchdog_SingleRegEnable);

/* 3.3V 供电下监视 0.4V ~ 2.8V 区间 */
/* 0.4V -> 0.4/3.3*4095 ≈ 496，2.8V -> 2.8/3.3*4095 ≈ 3474 */
ADC_AnalogWatchdogThresholdsConfig(ADC1, 3474, 496);
ADC_AnalogWatchdogSingleChannelConfig(ADC1, ADC_Channel_0);
ADC_AnalogWatchdogCmd(ADC1, ADC_AnalogWatchdog_SingleRegEnable);

/* 只监视 PA0 通道 */
ADC_AnalogWatchdogSingleChannelConfig(ADC1, ADC_Channel_0);
ADC_AnalogWatchdogCmd(ADC1, ADC_AnalogWatchdog_SingleRegEnable);

/* 用 Vrefint 反推 VDDA，做比例法电压测量 */
ADC_TempSensorVrefintCmd(ENABLE);

ADC_RegularChannelConfig(ADC1, ADC_Channel_17, 1, ADC_SampleTime_239Cycles5);
ADC_SoftwareStartConvCmd(ADC1, ENABLE);
while (ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC) == RESET);

vrefint = ADC_GetConversionValue(ADC1);
/* VDDA(mV) = 1200 * 4095 / vrefint */
vddamv = (uint32_t)1200 * 4095 / vrefint;

/* 温度传感器：T(C) = (V25 - Vsense)/Avg_Slope + 25，V25 与斜率见芯片数据手册 */

/* 轮询等待转换完成的标准写法 */
ADC_SoftwareStartConvCmd(ADC1, ENABLE);
while (ADC_GetFlagStatus(ADC1, ADC_FLAG_EOC) == RESET);
value = ADC_GetConversionValue(ADC1);   /* 读 DR 自动清 EOC */

/* 判断是否越限 */
if (ADC_GetFlagStatus(ADC1, ADC_FLAG_AWD) != RESET)
{
  ADC_ClearFlag(ADC1, ADC_FLAG_AWD);    /* AWD 必须手动清 */
}

/* 看门狗越限后必须清标志，否则一直保持置位 */
if (ADC_GetFlagStatus(ADC1, ADC_FLAG_AWD) != RESET)
{
  ADC_ClearFlag(ADC1, ADC_FLAG_AWD);
  /* 处理越限 */
}

void ADC1_2_IRQHandler(void)
{
  if (ADC_GetITStatus(ADC1, ADC_IT_EOC) != RESET)
  {
    adcValue = ADC_GetConversionValue(ADC1);   /* 读 DR 清 EOC */
  }
  if (ADC_GetITStatus(ADC1, ADC_IT_JEOC) != RESET)
  {
    injValue = ADC_GetInjectedConversionValue(ADC1, ADC_Channel_1);
  }
  if (ADC_GetITStatus(ADC1, ADC_IT_AWD) != RESET)
  {
    ADC_ClearITPendingBit(ADC1, ADC_IT_AWD);   /* AWD 必须软件清 */
  }
}

/* 看门狗越限中断必须手动清标志 */
if (ADC_GetITStatus(ADC1, ADC_IT_AWD) != RESET)
{
  ADC_ClearITPendingBit(ADC1, ADC_IT_AWD);
  /* 处理越限逻辑 */
}
